import type { Meta, StoryObj } from "@storybook/nextjs";
import { UnstyledTextField } from "./UnstyledTextField";
import { useState } from "react";

export default {
  title: "Design System/Atoms/UnstyledTextField",
  component: UnstyledTextField,
} as Meta<typeof UnstyledTextField>;

type Story = StoryObj<typeof UnstyledTextField>;

const Template: Story = {
  render: (args) => <UnstyledTextField {...args} />,
};

export const Default: Story = {
  ...Template,
  args: {
    placeholder: "Enter text...",
    type: "text",
  },
};

// Create a proper React component for the NumberInput story
const NumberInputComponent = (args: any) => {
  const [value, setValue] = useState("");
  
  return (
    <div style={{ background: '#1a1a1a', padding: '20px', borderRadius: '8px' }}>
      <UnstyledTextField
        {...args}
        variant="number"
        type="number"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder="0.000"
        step={0.001}
        min={0}
      />
    </div>
  );
};

export const NumberInput: Story = {
  render: (args) => <NumberInputComponent {...args} />,
  args: {
    variant: "number",
  },
  parameters: {
    design: {
      type: "figma",
      url: "https://www.figma.com/design/RAN3uFrg2IP79P8S4fpcul/Launchpad?node-id=23857-13942&t=1yeXhtvWmp7WohPF-0",
    },
  },
}; 